// === Process + Log (After Decryption) ===

// Pass through denied events
if (typeof msg.payload === "object" && msg.payload && msg.payload.event_type && msg.payload.event_type.startsWith("denied_")) {
    return msg;
}

let finalPayload;

try {
    finalPayload = JSON.parse(msg.payload);
} catch (e) {
    node.warn("Failed to parse Python output");
    finalPayload = msg.originalPayload || msg.payload;
}

if (finalPayload && finalPayload.error) {
    node.warn("Decryption failed: " + finalPayload.error);
    finalPayload = msg.originalPayload || {};
}

const topicParts = msg.topic.split("/");
const deviceId = topicParts[1] || msg.deviceId || "unknown";

const map = flow.get("clientIpMap") || {};
const ipInfo = map[deviceId] || { ip: "unknown" };

const gatewayReceivedAt = new Date().toISOString();
const deviceReportedAt = finalPayload.timestamp || null;

let delaySeconds = 0;
if (deviceReportedAt) {
    try {
        const grTime = new Date(gatewayReceivedAt);
        const drTime = new Date(deviceReportedAt);
        const diffMs = grTime.getTime() - drTime.getTime();
        delaySeconds = diffMs / 1000;
        if (delaySeconds < 0) delaySeconds = 0;
    } catch (e) {
        node.warn("Delay calculation failed: " + e.message);
        delaySeconds = 0;
    }
}

msg.payload = {
    gateway_received_at: gatewayReceivedAt,
    device_reported_at: deviceReportedAt,
    delay: parseFloat(delaySeconds.toFixed(3)),
    event_type: "sensor_data",
    deviceId: deviceId,
    username: deviceId,
    source_ip: ipInfo.ip || msg.source_ip,
    topic: msg.topic,
    payload: finalPayload,
    payload_size_bytes: msg.payload_size_bytes || 0,
    gateway: "pi-iot-gateway"
};

return msg;

const line = msg.payload.toString().trim();

const now = new Date().toISOString();

node.warn("[DEBUG Parse] line: " + line); 

// === 1. New Client Connected (Best source for IP + username) ===
if (line.includes("New client connected from")) {
    const ipMatch = line.match(/from ([\d.]+):\d+/);
    const clientIdMatch = line.match(/as ([\w-]+) /);
    const userMatch = line.match(/u'([^']+)'/);

    if (ipMatch && userMatch) {
        msg.payload = {
            type: "connection",
            timestamp: now,
            ip: ipMatch[1],
            username: userMatch[1],
            clientId: clientIdMatch ? clientIdMatch[1] : null
        };
        return [msg, null];
    }
}

// === 2. Connection from (fallback) ===
else if (line.includes("New connection from")) {
    const ipMatch = line.match(/from ([\d.]+):\d+/);
    if (ipMatch) {
        msg.payload = {
            type: "raw_connection",
            timestamp: now,
            ip: ipMatch[1]
        };
        return [msg, null];
    }
}

// === 3. Denied PUBLISH from ACL or other (provides clientId + attempted topic) ===
// This now catches cases like sensor4 publishing to sensors/sensor2/process (ACL violation)
else if (line.includes("Denied PUBLISH")) {
    // Primary regex for standard Mosquitto denied publish format
    const deniedMatch = line.match(/Denied PUBLISH from ([^\s(]+) \(d(\d+), q(\d+), r(\d+), m(\d+), '([^']+)', \.\.\. \((\d+) bytes\)\)/);
    let clientId, topic, bytes, dup = 0, qos = 0, retain = 0, mid = 0;

    if (deniedMatch) {
        clientId = deniedMatch[1];
        dup = parseInt(deniedMatch[2], 10);
        qos = parseInt(deniedMatch[3], 10);
        retain = parseInt(deniedMatch[4], 10);
        mid = parseInt(deniedMatch[5], 10);
        topic = deniedMatch[6];
        bytes = parseInt(deniedMatch[7], 10);
    } else {
        // Robust fallback: extract clientId and the topic inside single quotes
        const clientIdMatch = line.match(/Denied PUBLISH from ([^\s(]+)/);
        clientId = clientIdMatch ? clientIdMatch[1] : "unknown";

        const topicMatch = line.match(/'([^']+)'/);
        topic = topicMatch ? topicMatch[1] : "unknown";

        const bytesMatch = line.match(/\((\d+) bytes\)/);
        bytes = bytesMatch ? parseInt(bytesMatch[1], 10) : 0;
    }

    // Lookup IP/username using clientIdMap (populated when "New client connected" is seen)
    const cMap = flow.get("clientIdMap") || {};
    const info = cMap[clientId] || { ip: "unknown", username: null };
    let username = info.username || clientId;
    let ip = info.ip || "unknown";

    // Fallback to clientIpMap (username-based map)
    const uMap = flow.get("clientIpMap") || {};
    if (ip === "unknown" && uMap[clientId]) {
        ip = uMap[clientId].ip || "unknown";
        username = clientId;
    }

    msg.payload = {
        type: "denied_publish",
        timestamp: now,
        clientId: clientId,
        topic: topic,
        dup: dup,
        qos: qos,
        retain: retain,
        mid: mid,
        size: bytes,
        ip: ip,
        username: username,
        denied_type: "acl_publish"
    };
    return [null, msg];  // route to Prepare Denied Event
}


if (line.includes("Denied") || line.includes("denied")) {
    node.warn("[DEBUG] Broad catch triggered for denied line: " + line);
    // Broad catch-all for any denial log line (including ACL publish denials from sensor4 to sensor2 topic)
    // This ensures the event is always created even if specific regexes don't match the exact Mosquitto log format
    let topic = "unknown";
    const topicMatch = line.match(/'([^']+)'/);
    if (topicMatch) topic = topicMatch[1];
    let clientId = "unknown";
    const clientMatch = line.match(/from ([^\s(]+)/);
    if (clientMatch) clientId = clientMatch[1];
    msg.payload = {
        type: "denied_publish",
        timestamp: now,
        clientId: clientId,
        topic: topic,
        ip: "unknown",
        username: "unknown",
        raw: line,
        denied_type: "acl_publish"
    };
    return [null, msg];
}

return null;

// === Store Client IP - Function Node ===

if (msg.payload.type === "raw_connection" || !msg.payload.username) {
    return null;
}

if (!flow.get("clientIpMap")) {
    flow.set("clientIpMap", {});
}

const map = flow.get("clientIpMap");
const entry = {
    ip: msg.payload.ip,
    timestamp: Date.now()
};

map[msg.payload.username] = entry;

// Cleanup old entries (older than 10 minutes)
const now = Date.now();
for (let user in map) {
    if (now - map[user].timestamp > 600000) {
        delete map[user];
    }
}

flow.set("clientIpMap", map);

// === Also maintain clientIdMap so Denied PUBLISH (which logs clientId not username) can be correlated to IP ===
if (!flow.get("clientIdMap")) {
    flow.set("clientIdMap", {});
}

const cMap = flow.get("clientIdMap");
const cEntry = {
    ip: msg.payload.ip,
    username: msg.payload.username,
    timestamp: Date.now()
};
if (msg.payload.clientId) {
    cMap[msg.payload.clientId] = cEntry;
}

// cleanup clientIdMap
const cnow = Date.now();
for (let cid in cMap) {
    if (cnow - cMap[cid].timestamp > 600000) {
        delete cMap[cid];
    }
}
flow.set("clientIdMap", cMap);

return null;   // Important: no output

const p = msg.payload || {};
if (p.type !== "denied_publish" && p.type !== "denied_connect") { return null; }

const isPublish = p.type === "denied_publish";
const deviceId = (p.username && p.username !== "unknown") ? p.username : (p.clientId || "unknown");

msg.payload = {
    gateway_received_at: new Date().toISOString(),
    event_type: isPublish ? "denied_publish" : "denied_connect",
    deviceId: deviceId,
    username: p.username || "unknown",
    clientId: p.clientId || "unknown",
    source_ip: p.ip || "unknown",
    topic: p.topic || "unknown",
    qos: p.qos,
    retain: p.retain,
    size_bytes: p.size,
    denied_type: isPublish ? (p.denied_type || "acl_publish") : (p.denied_type || p.reason || "auth_failure"),
    reason: p.reason || null,
    gateway: "pi-iot-gateway"
};

return msg;

// Prepare for Decryption
const topicParts = msg.topic.split("/");
const deviceId = topicParts[1] || "unknown";

const map = flow.get("clientIpMap") || {};
const ipInfo = map[deviceId] || { ip: "unknown" };

// Save original
msg.originalPayload = msg.payload;

// Capture the raw incoming MQTT payload size (this is the "package size" of the encrypted message)
let incomingPayload = msg.payload;
if (typeof incomingPayload !== "string") {
    incomingPayload = JSON.stringify(incomingPayload || {});
}
msg.payload_size_bytes = Buffer.byteLength(incomingPayload, "utf8");

// Size restriction (keep existing logic)
const PAYLOAD_SIZE = 2802;
let payloadStr = typeof msg.payload === "string" ? msg.payload : JSON.stringify(msg.payload || {});
if (Math.abs(payloadStr.length - PAYLOAD_SIZE) > 50) {
    node.warn(`Payload size mismatch for device ${deviceId}: ${payloadStr.length} bytes (expected ~${PAYLOAD_SIZE})`);
    msg.payload = {
        gateway_received_at: new Date().toISOString(),
        event_type: "denied_payload_size",
        deviceId: deviceId,
        source_ip: ipInfo.ip || "unknown",
        denied_type: "payload_size_mismatch",
        reason: `Payload size ${payloadStr.length} does not match expected size`,
        payload_size_bytes: msg.payload_size_bytes,
        gateway: "pi-iot-gateway"
    };
    return msg;
}

// Ensure payload is a clean JSON string for Python
if (typeof msg.payload === "object") {
    msg.payload = JSON.stringify(msg.payload);
} else if (typeof msg.payload === "string") {
    try {
        JSON.parse(msg.payload); // validate
    } catch(e) {
        node.warn("Invalid JSON payload");
        return null;
    }
}

msg.deviceId = deviceId;
msg.source_ip = ipInfo.ip;

return msg;

function fernetDecrypt(tokenB64url, keyB64url) {
    const keyBuf = Buffer.from(keyB64url, 'base64');
    if (keyBuf.length !== 32) {
        throw new Error('Invalid key length: ' + keyBuf.length + ' (expected 32)');
    }
    const signingKey = keyBuf.slice(0, 16);
    const encryptionKey = keyBuf.slice(16, 32);

    const tokenBuf = Buffer.from(tokenB64url, 'base64');
    if (tokenBuf.length < 57) {
        throw new Error('Token too short: ' + tokenBuf.length);
    }

    const version = tokenBuf[0];
    if (version !== 0x80) {
        throw new Error('Unsupported Fernet version: 0x' + version.toString(16));
    }

    // Verify HMAC-SHA256
    const hmacData = tokenBuf.slice(0, tokenBuf.length - 32);
    const hmacGiven = tokenBuf.slice(tokenBuf.length - 32);
    const hmacCalc = crypto.createHmac('sha256', signingKey).update(hmacData).digest();
    if (!crypto.timingSafeEqual(hmacGiven, hmacCalc)) {
        throw new Error('HMAC verification failed — wrong key or corrupted data');
    }

    // Decrypt AES-128-CBC
    const iv = tokenBuf.slice(9, 25);
    const ciphertext = tokenBuf.slice(25, tokenBuf.length - 32);
    const decipher = crypto.createDecipheriv('aes-128-cbc', encryptionKey, iv);
    const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);

    return JSON.parse(decrypted.toString('utf8'));
}

try {
    // Pass through pre-created denied events (e.g. payload size from prepare)
    if (typeof msg.payload === 'object' && msg.payload && msg.payload.event_type && msg.payload.event_type.startsWith('denied_')) {
        return msg;
    }

    let wrapper = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;

    const key = wrapper.key;
    const encrypted = wrapper.encrypted;

    if (!key || !encrypted) {
        node.warn('Missing "key" or "encrypted" — forwarding as-is');
        msg.payload = JSON.stringify(wrapper);
        return msg;
    }

    const decrypted = fernetDecrypt(encrypted, key);

    msg.payload = JSON.stringify(decrypted);
    return msg;

} catch (e) {
    node.warn('Fernet decryption error: ' + e.message);
    msg.payload = {
        gateway_received_at: now,
        event_type: "denied_decryption",
        deviceId: msg.deviceId || "unknown",
        source_ip: msg.source_ip || "unknown",
        denied_type: "decryption_failure",
        reason: "Message could not be decrypted (encrypted with incompatible/different method or wrong/corrupted key). " + e.message,
        gateway: "pi-iot-gateway"
    };
    return msg;
}
